<?php
declare(strict_types=1);
namespace Namira;
use PDO;
final class StoreFiles {
 public static function put(PDO $db,array|false $actor,string $source,string $name,string $kind,array $scope=[]):int {
 $settings=StoreSettings::get($db);$name=basename(str_replace('\\','/',$name));$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($source);$size=filesize($source);if(!$size||$size>$settings['upload_mb']*1048576||mb_strlen($name)>255)throw new HttpError(422,'حجم یا نام فایل مجاز نیست.');$meta=null;
 if(in_array($ext,['jpg','jpeg','png','webp'],true))$meta=Upload::validate($source);
 elseif($ext==='pdf'){if($mime!=='application/pdf'||file_get_contents($source,false,null,0,5)!=='%PDF-')throw new HttpError(422,'PDF معتبر نیست.');}
 elseif($ext==='psd'){if(file_get_contents($source,false,null,0,4)!=='8BPS')throw new HttpError(422,'PSD معتبر نیست.');$mime='image/vnd.adobe.photoshop';}
 elseif($ext==='zip'){$zip=new \ZipArchive();if($zip->open($source)!==true)throw new HttpError(422,'ZIP معتبر نیست.');try{$total=0;if($zip->numFiles>500)throw new HttpError(422,'اجزای فایل فشرده زیاد است.');for($n=0;$n<$zip->numFiles;$n++){$entry=$zip->statIndex($n);$total+=$entry['size'];if($total>200*1048576||str_contains($entry['name'],'..')||preg_match('/\.(php\d?|phtml|phar|exe|js|html|svg|bat|cmd|sh)$/i',$entry['name']))throw new HttpError(422,'محتوای فایل فشرده مجاز نیست.');}}finally{$zip->close();}$mime='application/zip';}
 else throw new HttpError(422,'فرمت فایل مجاز نیست.');
 $cart=null;$item=null;$product=null;
 if($kind==='input'){$cart=StoreCart::token($db,$actor);$field=Security::text($scope,'field_key',80);$p=(new StoreCatalog($db))->get(StoreCatalog::integer($scope['product_id']??0,1));$form=StoreForms::forProduct($db,$p);$f=null;foreach($form['fields'] as $def)if($def['key']===$field)$f=$def;if(!$f||!in_array($f['type'],['image','file'],true)||!in_array($ext,$f['formats'],true)||($f['type']==='image'&&!$meta)||$size>$f['max_mb']*1048576)throw new HttpError(422,'فایل با فیلد محصول سازگار نیست.');$product=(int)$p['id'];}
 elseif($kind==='catalog'){if(!Permissions::allows($db,$actor,'shop.manage'))throw new HttpError(403,'فایل کاتالوگ فقط برای مدیر فروشگاه مجاز است.');$product=StoreCatalog::integer($scope['product_id']??0,1);(new StoreCatalog($db))->get($product,true);$field='';}
 elseif(in_array($kind,['proof','final','message'],true)){if(!$actor)throw new HttpError(403,'ورود لازم است.');$item=StoreCatalog::integer($scope['item_id']??0,1);$i=StoreAccess::item($db,$item,$actor,$kind==='message'?'read':'design');if($kind==='proof'&&!$meta)throw new HttpError(422,'پیش‌نمایش باید تصویر باشد.');$field='';if(in_array($kind,['proof','final'],true)&&!Db::query($db,"SELECT id FROM payments WHERE order_id=? AND status='verified'",[$i['order_id']])->fetchColumn()&&$i['status']!=='designing')throw new HttpError(422,'ابتدا پرداخت یا مجوز صریح شروع طراحی ثبت شود.');}
 else throw new HttpError(422,'کاربرد فایل معتبر نیست.');
 $folder=Env::storage().'/store-private';if(!is_dir($folder))mkdir($folder,0700,true);file_put_contents($folder.'/.htaccess',"Require all denied\n");$relative='store-private/'.bin2hex(random_bytes(24)).'.'.$ext;$preview='';
 try{if(!copy($source,Env::storage().'/'.$relative))throw new HttpError(503,'فایل ذخیره نشد.');chmod(Env::storage().'/'.$relative,0600);
 if($meta){Upload::assertDecodeMemory($meta);$im=match($meta['mime']){'image/jpeg'=>@imagecreatefromjpeg($source),'image/png'=>@imagecreatefrompng($source),'image/webp'=>@imagecreatefromwebp($source)};if(!$im)throw new HttpError(422,'تصویر قابل خواندن نیست.');$ratio=min(1,800/max($meta['width'],$meta['height']));$w=max(1,(int)round($meta['width']*$ratio));$h=max(1,(int)round($meta['height']*$ratio));$out=imagecreatetruecolor($w,$h);imagealphablending($out,false);imagesavealpha($out,true);imagecopyresampled($out,$im,0,0,0,0,$w,$h,$meta['width'],$meta['height']);$preview='store-private/'.bin2hex(random_bytes(24)).'.webp';if(!imagewebp($out,Env::storage().'/'.$preview,80))throw new HttpError(503,'پیش‌نمایش ذخیره نشد.');chmod(Env::storage().'/'.$preview,0600);unset($im,$out);}
 return Db::transaction($db,function()use($db,$actor,$cart,$item,$product,$field,$kind,$relative,$preview,$mime,$size,$source,$name,$settings){$id=Db::insert($db,'store_files',['owner_id'=>$actor['id']??null,'cart_token'=>$cart,'item_id'=>$item,'product_id'=>$product,'field_key'=>$field,'kind'=>$kind,'path'=>$relative,'preview_path'=>$preview,'mime'=>$mime,'bytes'=>$size,'sha256'=>hash_file('sha256',$source),'filename'=>$name,'active'=>1,'download_limit'=>$kind==='catalog'?$settings['download_limit']:0,'expires_at'=>0,'created_at'=>date(DATE_ATOM)]);if($kind==='final')Db::query($db,"UPDATE store_item_details SET digital_state='pending',approved_proof_id=CASE WHEN approval_required=1 THEN NULL ELSE approved_proof_id END,status=CASE WHEN status='ready' THEN 'designing' ELSE status END,revision=revision+1 WHERE item_id=?",[$item]);return $id;});
 }catch(\Throwable $e){foreach([$relative,$preview] as $p)if($p&&is_file(Env::storage().'/'.$p))unlink(Env::storage().'/'.$p);throw $e;}
 }
 public static function authorize(PDO $db,int $id,array|false $actor,int $entitlement=0,bool $count=false):array {
 return Db::transaction($db,function()use($db,$id,$actor,$entitlement,$count){$f=Db::query($db,'SELECT * FROM store_files WHERE id=?'.StoreAccess::lock($db),[$id])->fetch();if(!$f||!$f['active']||($f['expires_at']&&$f['expires_at']<time()))throw new HttpError(404,'فایل در دسترس نیست.');$allowed=false;$customer=false;$i=null;
 if($f['kind']==='input'&&$f['cart_token']&&hash_equals(StoreCart::token($db,$actor),(string)$f['cart_token']))$allowed=true;
 if($actor){if(StoreAccess::allows($db,$actor,'orders'))$allowed=true;
 if($f['item_id']){try{$i=StoreAccess::item($db,(int)$f['item_id'],$actor);$owner=StoreAccess::owner($db,(int)$i['order_id'],$actor);$assigned=StoreAccess::allows($db,$actor,'design')&&(int)$i['assigned_user_id']===(int)$actor['id'];$production=StoreAccess::allows($db,$actor,'production')&&in_array($f['kind'],['final','proof'],true);if($owner&&in_array($f['kind'],['input','proof','message'],true))$allowed=true;if($assigned||$production)$allowed=true;if($owner&&$f['kind']==='final'){$entitlement=(int)$i['item_id'];$customer=true;}}catch(HttpError){}}
 if($entitlement){$i=StoreAccess::item($db,$entitlement,$actor,'customer');$snap=Protocol::decode($i['snapshot']);$paid=Db::query($db,"SELECT id FROM payments WHERE order_id=? AND status='verified'",[$i['order_id']])->fetchColumn();$linked=($f['kind']==='final'&&(int)$f['item_id']===$entitlement)||($f['kind']==='catalog'&&in_array($id,array_map('intval',$snap['digital_files']??[]),true));if($paid&&$linked&&in_array($i['digital_state'],['available','downloaded'],true)&&!in_array($i['status'],['cancelled','returned'],true)){$allowed=true;$customer=true;}else if($customer)$allowed=false;}
 }
 if(!$allowed)throw new HttpError(404,'فایل در دسترس نیست.');if(!is_file(Upload::absolute($f['path'])))throw new HttpError(404,'فایل در دسترس نیست.');
 if($count&&$customer){$used=(int)Db::query($db,'SELECT COUNT(*) FROM store_download_events WHERE file_id=? AND user_id=? AND item_id=?',[$id,$actor['id'],$entitlement])->fetchColumn();$settings=StoreSettings::get($db);$limit=(int)($i?Protocol::decode($i['snapshot'])['download_limit']??0:0);if($limit&&$used>=$limit)throw new HttpError(403,'سقف دریافت این خرید تکمیل شده است.');$snap=Protocol::decode($i['snapshot']);if(($i['download_until']??0)&&$i['download_until']<time())throw new HttpError(403,'مهلت دریافت این خرید پایان یافته است.');Db::insert($db,'store_download_events',['file_id'=>$id,'user_id'=>$actor['id'],'item_id'=>$entitlement,'created_at'=>date(DATE_ATOM)]);Db::query($db,'UPDATE store_files SET downloads=downloads+1 WHERE id=?',[$id]);Db::query($db,"UPDATE store_item_details SET digital_state='downloaded' WHERE item_id=?",[$entitlement]);}
 return $f;
 });
 }
}
